// App.js
import React from "react";
import { Authenticator, useAuthenticator } from "@aws-amplify/ui-react";
import "@aws-amplify/ui-react/styles.css";
import TaskList from "./components/TaskList";

function App() {
  const { route, user, signOut } = useAuthenticator((context) => [
    context.route,
    context.user,
  ]);

  // Authenticated view
  if (route === "authenticated") {
    console.log("Logged in user:", user);
    return (
      <div className="App">
        {/* Social login attributes are sometimes inside signInDetails */}
        <h2>Welcome, {user?.signInDetails?.loginId || user?.username}</h2>
        <button onClick={signOut}>Sign Out</button>
        <TaskList />
      </div>
    );
  }

  // Sign-in view
  return (
    <div style={{ marginTop: '50px' }}>
      <Authenticator socialProviders={["google"]} hideSignUp={true} />
    </div>
  );
}

export default App;
