import axios from 'axios';

// 1. Use your actual EC2 IP (until you set up your domain)
const API_URL = 'http://18.234.247.48:3000/tasks'; 

// 2. Get all tasks for a specific user
export const getTasks = (userId) => 
  axios.get(`${API_URL}?userId=${userId}`);

// 3. Create a new task (Include the userId in the body)
export const createTask = (task) => 
  axios.post(API_URL, task); 

// 4. Update a task (Pass userId in body for ownership check)
export const updateTask = (id, updates, userId) => 
  axios.put(`${API_URL}/${id}`, { ...updates, userId });

// 5. Delete a task (Pass userId in query)
export const deleteTask = (id, userId) => 
  axios.delete(`${API_URL}/${id}?userId=${userId}`);